WITH base AS (SELECT *, CASE WHEN budget >= 3911000 THEN 'High' WHEN budget >= 1309000 THEN 'Medium' ELSE 'Low' END AS budget_tier, CASE WHEN location = 'New York' THEN 1 ELSE 0 END AS is_new_york FROM departments WHERE dept_name IN ('Engineering', 'Finance')) SELECT CASE WHEN budget >= 3810000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, COUNT(*) AS cnt, COUNT(*) AS row_count, COUNT(DISTINCT dept_name) AS distinct_dept_names, STDDEV_SAMP(budget) AS budget_stddev FROM base GROUP BY 1 ORDER BY budget_tier DESC NULLS LAST
